{
  # Global options
  # 管理面无认证：原来是 `admin :2019`，而 Service 还导出了 admin 端口，
  # 等于集群里任一无认证 pod 都能读生效配置（含替换后的 CrowdSec key）并 POST /load 重配 v6 入口。
  # 全仓没有任何消费者（ScrapeConfig 只抓 VPS/sakamoto 的 2019，Homepage 没配它的 widget），直接关掉。
  # 关掉后 Caddyfile 变更仍由 ConfigMap + Reloader 重建 pod 生效；要临时手动 reload 就改回 localhost:2019。
  admin off
  log {
    level DEBUG
  }
  servers {
    #trusted_proxies static private_ranges 100.96.0.0/11 # 信任局域网的XFF头
    protocols h1 h2 h3
  }
  crowdsec {
    api_url http://crowdsec-service.security.svc.cluster.local:8080
    api_key {$CROWDSEC_API_KEY}
    ticker_interval 15s
    appsec_url http://crowdsec-appsec-service.security.svc.cluster.local:7422
  }
}

:8080 {
  handle /health {
    respond "OK" 200
  }
}

(with-tls) {
  tls /etc/caddy/tls/tls.crt /etc/caddy/tls/tls.key
}
(to_external) {
  reverse_proxy {
    to https://envoy-external.network.svc.cluster.local:443
    header_up Host {http.request.host}
    transport http {
      tls
      tls_server_name {http.request.host}
    }
  }
}
(common_header) {
  header {
    +My-Server "caddy-external"
    -Server
    -via
  }
}
*.{$MAIN_DOMAIN} {
  import with-tls

  # 机器对机器的 WebDAV（Basic 认证）不经 AppSec：PROPFIND 的 XML body 会命中 CRS 901340，out-of-band 事件累计后封出口 IP（#1705）
  @waf not {
    host drive.{$MAIN_DOMAIN}
    path /dav /dav/*
  }

  route {
    crowdsec
    appsec @waf

    handle {
      import to_external
      import common_header
    }
  }
}
